// Flag definitions controlling optimization thresholds and tiering decisions

// Default optimization thresholds (from flags/flag-definitions.h)
DEFINE_INT(invocation_count_for_maglev, 1000,
           "number of invocations before maglev gets triggered")
DEFINE_INT(invocation_count_for_turbofan, 3000,
           "number of invocations before turbofan gets triggered")
DEFINE_INT(invocation_count_for_early_optimization, 30,
           "number of invocations before early optimization gets triggered")
DEFINE_INT(invocation_count_for_maglev_with_delay, 600,
           "number of invocations before maglev gets triggered with delay")
DEFINE_INT(invocation_count_for_feedback_allocation, 5,
           "number of invocations before feedback vector gets allocated")
DEFINE_INT(invocation_count_for_osr, 100,
           "number of invocations before OSR gets triggered")
DEFINE_INT(invocation_count_for_maglev_osr, 100,
           "number of invocations before maglev OSR gets triggered")

// Bytecode size limits
DEFINE_INT(max_optimized_bytecode_size, 60 * KB,
           "maximum bytecode size for optimization")

// Tiering control flags
DEFINE_BOOL(profile_guided_optimization, true,
            "enable profile guided optimization")
DEFINE_BOOL(concurrent_recompilation, true,
            "enable concurrent recompilation")
DEFINE_BOOL(concurrent_osr, true,
            "enable concurrent on-stack replacement")
DEFINE_BOOL(use_osr, true,
            "enable on-stack replacement")

// Tier-specific enable flags
DEFINE_BOOL(maglev, V8_ENABLE_MAGLEV_BOOL,
            "enable Maglev compiler")
DEFINE_BOOL(turbofan, V8_ENABLE_TURBOFAN_BOOL,
            "enable Turbofan compiler")

// Filter flags for selective optimization
DEFINE_STRING(maglev_filter, "*",
              "filter to select functions for maglev optimization")
DEFINE_STRING(turbo_filter, "*",
              "filter to select functions for turbofan optimization")

// Efficiency mode adjustments
DEFINE_BOOL(efficiency_mode_disable_turbofan, false,
            "disable turbofan in efficiency mode")
DEFINE_INT(efficiency_mode_delay_turbofan_multiply, 4,
           "multiply turbofan invocation count in efficiency mode")

// Stress testing flags
DEFINE_VALUE_IMPLICATION(jit_fuzzing, invocation_count_for_maglev, 10)
DEFINE_VALUE_IMPLICATION(jit_fuzzing, invocation_count_for_turbofan, 20)
DEFINE_VALUE_IMPLICATION(jit_fuzzing, invocation_count_for_maglev_osr, 1)

// How thresholds are used in tiering decisions:
// 1. First, function needs invocation_count_for_feedback_allocation * bytecode_length
//    invocations to allocate feedback vector
// 2. Then needs invocation_count_for_maglev * bytecode_length invocations for Maglev
// 3. Finally needs invocation_count_for_turbofan * bytecode_length for Turbofan
// 4. Early optimization can trigger at invocation_count_for_early_optimization
//    if profile guided optimization suggests it's beneficial

// Example calculation from tiering-manager.cc:
// return v8_flags.invocation_count_for_maglev * bytecode_length;
// return v8_flags.invocation_count_for_turbofan * bytecode_length;
// return v8_flags.invocation_count_for_early_optimization * bytecode_length;
